import type { FaceConfigState } from "../face-engine/faceConfigState";
import { emitVerbEnum, emitVerbSlugTable, emitVerbToExpressionTable } from "./emitSchemaEnums";

export function emitVerbEnumH(config: FaceConfigState): string {
    return `#pragma once

/**
 * @file VerbEnum.generated.h
 * @brief Generated verb ids — system verbs first, then custom editor verbs.
 *
 * Generated by face-editor POST /api/saveData. Included from VerbSystem.h.
 * EventRouter uses only the system verb enumerators (Thinking … AttractingAttention).
 */

#include "FACE_CONFIG_DATA.h"

namespace VerbSystem {

${emitVerbEnum(config)}

}  // namespace VerbSystem

namespace FaceConfig {

${emitVerbToExpressionTable(config)}

${emitVerbSlugTable(config)}

}  // namespace FaceConfig
`;
}
